# reliability for 2010
dc_tracts2010 <- dc_tracts2010 %>%
  filter(total_popE > 0) %>%
  mutate(
    below_pov_se = below_povM / 1.645,   #below poverty standard error
    below_pov_cv = (below_pov_se / below_povE) * 100,
    reliability = case_when(
      below_pov_cv < 12  ~ "High",
      below_pov_cv <= 40 ~ "Moderate",
      TRUE             ~ "Low"
    )
  )
