::: {.cell}

```{.r .cell-code}
# changed the most
top_change = dc_poverty_tested %>%
  filter(significant) %>%
  arrange(desc(abs(change))) %>%
  slice_head(n = 32)
```
:::



::: {.cell}

```{.r .cell-code}
dc_change_map = dc_tracts2015 %>%
  left_join(dc_poverty_tested %>% select(NAME, change), by = "NAME")   ##dc_tracts 2015 still had the geometry so im usimg it to make the map
```
:::



::: {.cell}

```{.r .cell-code}
dc_top_change = dc_change_map %>%
  filter(NAME %in% top_change$NAME)
```
:::



::: {.cell}

```{.r .cell-code}
ggplot(dc_change_map) +
  geom_sf(aes(fill = change), color = NA) +
  geom_sf(data = dc_top_change, fill = NA, color = "black") +
  scale_fill_gradient2(low = "midnightblue", mid = "white", high = "firebrick3") +
  theme_void() +
  labs(title = "DC tracts with the significant change in Black poverty",
       subtitle = "2006-2010 vs 2011-2015, ACS 5-year estimates",
       fill = "Change",
       caption = "Black outlines show the 32 tracts with the largest significant change.")
```

